package lk.ac.nibm.hdse.fixly_20.data.repository

import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.GeoPoint
import kotlinx.coroutines.tasks.await
import lk.ac.nibm.hdse.fixly_20.model.JobPost

class JobRepository(
    private val firebaseAuth: FirebaseAuth = FirebaseAuth.getInstance(),
    private val firestore: FirebaseFirestore = FirebaseFirestore.getInstance()
) {

    /**
     * Creates a new job post document under "jobPosts".
     * The document ID is generated by Firestore and written back into the job itself.
     */
    suspend fun postJob(
        customerName: String,
        category: String,
        description: String,
        preferredDate: String,
        preferredTime: String,
        isEmergency: Boolean,
        location: GeoPoint?,
        address: String
    ): Result<String> {
        return try {
            val customerId = firebaseAuth.currentUser?.uid
                ?: return Result.failure(IllegalStateException("No logged-in user"))

            val docRef = firestore.collection("jobPosts").document() // auto-generated ID

            val job = JobPost(
                jobId = docRef.id,
                customerId = customerId,
                customerName = customerName,
                category = category,
                description = description,
                preferredDate = preferredDate,
                preferredTime = preferredTime,
                isEmergency = isEmergency,
                location = location,
                address = address,
                status = "Open"
            )

            docRef.set(job).await()
            Result.success(docRef.id)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
